          const productPrice = price || item.priceText || item.price || "";
          const explicitProductClip = item.productClip === true || item.isProductClip === true || item.productClipDetails || /product\s*clip|shared\s+a\s+product\s+clip|product\s+video|clip\s+product/.test(tag);
          const hasProductFields = !!(productPrice || item.productTitle || item.productName || item.productDescription || item.productInfo || item.productText);
          return {
            isProductClip: !!(explicitProductClip || hasProductFields),
            title: item.productTitle || item.productName || title || "Product",
            description: item.productDescription || item.productInfo || item.productText || description || "Fresh item with clear product details.",
            price: productPrice
          };
