            const mediaValues = [data.mediaRef, data.videoRef, data.imageRef, data.posterRef, data.thumbnailRef, data.mediaSrc, data.video, data.videoSrc, data.image, data.imageSrc, data.posterSrc, data.thumbnailSrc];
