              const rowBusiness = slug(row.businessName || row.business || row.actor || row.name || row.key || row.businessKey);
              let score = priority;
              if (rowKeys.some((key) => wantedKeys.has(key))) score += 120;
              if (wantedTitle && rowTitle && (wantedTitle === rowTitle || wantedTitle.indexOf(rowTitle) >= 0 || rowTitle.indexOf(wantedTitle) >= 0)) score += 45;
              if (wantedBusiness && rowBusiness && (wantedBusiness === rowBusiness || wantedBusiness.indexOf(rowBusiness) >= 0 || rowBusiness.indexOf(wantedBusiness) >= 0)) score += 20;
