        function markHomeInteractionWindow() {
          window.__EMY_HOME_INTERACTION_UNTIL__ = Date.now() + 2200;
        }

        function homeInteractionActive() {
          return Date.now() < (Number(window.__EMY_HOME_INTERACTION_UNTIL__) || 0);
        }

        function markHomeActivationWindow() {
          if (document.hidden) return;
          window.__EMY_HOME_ACTIVATION_UNTIL__ = Date.now() + 1400;
        }

        function homeActivationActive() {
          return Date.now() < (Number(window.__EMY_HOME_ACTIVATION_UNTIL__) || 0);
        }

        function scheduleHomeActivationTask(key, callback, delay = 4200, timeout = 1200) {
          const taskKey = key || "default";
          const timers = window.__EMY_HOME_ACTIVATION_TIMERS__ || (window.__EMY_HOME_ACTIVATION_TIMERS__ = {});
          if (timers[taskKey]) window.clearTimeout(timers[taskKey]);
          const run = () => {
            if (homeInteractionActive() || homeActivationActive()) {
              timers[taskKey] = window.setTimeout(run, homeInteractionActive() ? 900 : 420);
              return;
            }
            delete timers[taskKey];
            scheduleHomeStartupTask(callback, timeout);
          };
          timers[taskKey] = window.setTimeout(run, delay);
        }

        window.emyHomeInteractionActive = homeInteractionActive;
        window.emyHomeActivationActive = homeActivationActive;
        window.emyMarkHomeActivation = markHomeActivationWindow;
