            disliked: !!(row.querySelector("[data-feed-comment-dislike]") && row.querySelector("[data-feed-comment-dislike]").classList.contains("is-active")),
            own,
            mine: own,
            createdAt: row.dataset.feedCommentCreatedAt || new Date().toISOString(),
