          const skipHydrate = action === "delete" || action === "create" || action === "edit" || !!(opts.detail && opts.detail.deleted);
          const currentView = document.body ? (document.body.dataset.currentView || "home") : "home";
          const onFeedsView = isOnCustomerFeedsView();
