          const isVideo = annexedComposePendingMediaType === "video";
          if (feedComposeSourceTitle) feedComposeSourceTitle.textContent = isVideo ? "Add video" : "Add photo";
          if (feedComposeSourceHelp) feedComposeSourceHelp.textContent = isVideo ? "Choose from gallery, computer, or record now." : "Choose from gallery, computer, or take a picture now.";
          if (feedComposeLibraryTitle) feedComposeLibraryTitle.textContent = "Gallery or computer";
          if (feedComposeLibraryHelp) feedComposeLibraryHelp.textContent = isVideo ? "Choose a saved video from your phone gallery, laptop, or files." : "Choose a photo from your phone gallery, laptop, or files.";
          if (feedComposeCameraTitle) feedComposeCameraTitle.textContent = isVideo ? "Record video now" : "Take picture now";
          if (feedComposeCameraHelp) feedComposeCameraHelp.textContent = isVideo ? "Use your camera to record a new video if available." : "Use your camera to take a new picture if available.";
          setAnnexedComposeSourceOpen(true);
